workedExamples.verify:
from fractions import Fraction

def h(x):
    return 4 ** x - 9 * 2 ** x + 8

N = 20000
xs = [-10 + 20 * i / N for i in range(N + 1)]
roots = []
for a, b in zip(xs, xs[1:]):
    if h(a) == 0:
        roots.append(a)
    elif h(a) * h(b) < 0:
        lo, hi = a, b
        for _ in range(100):
            mid = (lo + hi) / 2
            if h(lo) * h(mid) <= 0:
                hi = mid
            else:
                lo = mid
        roots.append((lo + hi) / 2)
print(Fraction(round(sum(roots), 6)).limit_denominator(100))

