import math

def is_square(v):
    r = math.isqrt(v)
    return r * r == v

count = 0
for m in range(1, 101):
    for n in range(1, 101):
        if is_square(2 ** m + 2 ** n):
            count += 1
print(count)

from fractions import Fraction as F

sols = []
for i in range(-40, 41):
    for j in range(-40, 41):
        p, q = F(i, 4), F(j, 4)
        if p + q / 2 == 4 and p / 2 + q == 5:
            sols.append((p, q))
assert len(sols) == 1
p, q = sols[0]
print(2 ** int(p + q))

def f(n):
    k = 0
    while 3 ** (k + 1) <= n:
        k += 1
    # now 3^k <= n < 3^(k+1)
    if n <= 2 * 3 ** k:
        return n + 3 ** k
    return 3 * n - 3 ** (k + 1)

assert all(f(f(n)) == 3 * n for n in range(1, 3001))
assert all(f(n) < f(n + 1) for n in range(1, 3000))
print(f(2025))

def floor_log(base, n):
    j = 0
    while base ** (j + 1) <= n:
        j += 1
    return j

count = 0
for n in range(1, 1001):
    if floor_log(2, n) == floor_log(3, n) + 1:
        count += 1
print(count)
